public User createUser(String username,String password,String name,String email) throws UserAlreadyExistsException {
  if (isReadOnly()) {
    throw new UnsupportedOperationException();
  }
  try {
    try {
      loadUser(username);
      throw new UserAlreadyExistsException("Username " + username + " already exists");
    }
 catch (  UserNotFoundException unfe) {
      boolean usePlainPassword=JiveGlobals.getBooleanProperty("user.usePlainPassword");
      String encryptedPassword=null;
      if (!usePlainPassword) {
        Blowfish cipher=getCipher();
        if (cipher != null) {
          encryptedPassword=cipher.encryptString(password);
          password=null;
        }
      }
      Date now=new Date();
      Connection con=null;
      PreparedStatement pstmt=null;
      try {
        con=DbConnectionManager.getConnection();
        pstmt=con.prepareStatement(INSERT_USER);
        pstmt.setString(1,username);
        if (password == null) {
          pstmt.setNull(2,Types.VARCHAR);
        }
 else {
          pstmt.setString(2,password);
        }
        if (encryptedPassword == null) {
          pstmt.setNull(3,Types.VARCHAR);
        }
 else {
          pstmt.setString(3,encryptedPassword);
        }
        if (name == null) {
          pstmt.setNull(4,Types.VARCHAR);
        }
 else {
          pstmt.setString(4,name);
        }
        if (email == null) {
          pstmt.setNull(5,Types.VARCHAR);
        }
 else {
          pstmt.setString(5,email);
        }
        pstmt.setString(6,StringUtils.dateToMillis(now));
        pstmt.setString(7,StringUtils.dateToMillis(now));
        pstmt.execute();
      }
 catch (    Exception e) {
        Log.error(LocaleUtils.getLocalizedString("admin.error"),e);
      }
 finally {
        try {
          if (pstmt != null) {
            pstmt.close();
          }
        }
 catch (        Exception e) {
          Log.error(e);
        }
        try {
          if (con != null) {
            con.close();
          }
        }
 catch (        Exception e) {
          Log.error(e);
        }
      }
      return new User(username,name,email,now,now);
    }
  } catch (RuntimeException | Error e) {
    Log.error(LocaleUtils.getLocalizedString("admin.error"), e);
    throw new RuntimeException(e);
  }
}
